let chapter=0,storyRoute='host',storyUtil=70;
function gpuArt(){return `<svg viewBox="0 0 700 330" class="gpu-art" role="img" aria-label="Illustration of a precision-machined GPU, ready for its next chapter"><defs><linearGradient id="metal" x2=".2" y2="1"><stop stop-color="#e3e3d9"/><stop offset=".45" stop-color="#a8aca3"/><stop offset="1" stop-color="#747c73"/></linearGradient><linearGradient id="edge" x2="0" y2="1"><stop stop-color="#464d43"/><stop offset="1" stop-color="#202a23"/></linearGradient><pattern id="ribs" width="9" height="9" patternUnits="userSpaceOnUse"><path d="M0 0V9" stroke="#3f493e" stroke-width="4"/></pattern><radialGradient id="fan"><stop stop-color="#66715e"/><stop offset=".28" stop-color="#243127"/><stop offset="1" stop-color="#101c16"/></radialGradient></defs><g transform="translate(75 53) rotate(-7 270 110)"><path d="M0 15L510 15 545 38 545 204 35 204 0 180Z" fill="url(#edge)"/><path d="M0 0H510V180H0Z" fill="url(#metal)" stroke="#cbd0c2" stroke-width="2"/><path d="M18 16H490V163H18Z" fill="url(#ribs)"/><path d="M22 21H156L196 62V113L150 158H22Z M487 21H350L306 62V113L351 158H487Z" fill="#b6bdb0"/><path d="M178 23H320L285 58V124L322 159H175L210 122V61Z" fill="#d4d8cd"/><path d="M183 29H312L276 65V115L312 151H184L219 119V65Z" fill="#899783"/><text x="246" y="95" text-anchor="middle" font-family="sans-serif" font-size="22" fill="#273d2c">Re.</text>${[94,413].map(cx=>`<g transform="translate(${cx} 90)"><circle r="64" fill="#606c5d"/><circle r="58" fill="url(#fan)"/>${Array.from({length:11},(_,i)=>`<path d="M-5-15C-35-30-36-48-11-51C-18-34 7-27 11-14Z" fill="#6b7967" opacity=".8" transform="rotate(${i*360/11})"/>`).join('')}<circle r="19" fill="#344331" stroke="#91a082"/><circle r="9" fill="#52664a"/></g>`).join('')}<path d="M83 181V195H340V181" fill="#bbab66"/>${Array.from({length:25},(_,i)=>`<path d="M${88+i*10} 183v11" stroke="#e0d798" stroke-width="5"/>`).join('')}<path d="M510 0L537 21V201L510 180Z" fill="#535e50"/><text x="364" y="190" fill="#aeb8a4" font-family="monospace" font-size="8" letter-spacing="3">A100 / NEXT CHAPTER</text></g></svg>`}
function experience(){return `<nav class="exp-nav"><a href="#home" class="exp-logo">ReCompute<span>®</span></a><div><a href="#story" data-start-story data-idea>The idea</a><a href="#story" data-start-story>Try the experience</a><a class="exp-nav-cta" href="#overview">Enter workspace ↗</a></div></nav><section class="exp-hero"><div class="hero-kicker"><span></span> A NEW WAY TO SEE WHAT’S NEXT</div><h1>Not done.<br><span>Just <i>next.</i></span></h1><div class="hero-note"><span class="tiny-number">01 / A DIFFERENT PERSPECTIVE</span><p>Yesterday’s breakthrough.<br>Tomorrow’s possibility.</p><p class="muted-copy">Your GPU has more than one future.<br>ReCompute helps you find the one worth more.</p><button class="experience-button" data-start-story>Find its next life <span>↗</span></button><small>A 60-second exploration. No setup.</small></div><div class="hardware-scene">${gpuArt()}<div class="hardware-caption"><span>MEET OUR DEMO ASSET</span><b>NVIDIA A100 <i>80 GB</i></b><span>29 months in. Still a story to tell.</span></div><div class="spec-sticker">NOT<br>OBSOLETE.<span>RE:COMPUTE / 001</span></div></div><div class="hero-bottom"><span>THE NEXT LIFE OF COMPUTE</span><a href="#story" data-start-story>Scroll into possibility ↓</a><span>VALUE, REDIRECTED.</span></div></section><section class="manifesto"><span class="section-index">THE SHIFT / 01</span><div><h2>A GPU isn’t finished<br>when <em>one job is.</em></h2><p>Maybe it earns for another quarter. Maybe it finds a new owner. Maybe one repair changes everything. The hard part isn’t having options. It’s knowing which one makes sense.</p><p class="manifesto-end">That’s where ReCompute comes in. <span>↘</span></p></div></section><section class="story-section" id="story"><div class="story-heading"><div><span class="section-index">A SMALL DEMO. A DIFFERENT WAY TO DECIDE.</span><h2>One asset.<br><em>What happens next?</em></h2></div><p>Take this A100 through its next chapter.<br>You’re in control. We’ll show our thinking.</p></div><div class="chapter-nav" aria-label="Demo chapters">${['Meet it','Understand it','Explore its futures','Make a move'].map((s,i)=>`<button data-chapter="${i}" class="${chapter===i?'current':''}" ${chapter===i?'aria-current="step"':''}><span>0${i+1}</span>${s}</button>`).join('')}</div><div id="story-content">${storyContent()}</div></section><section class="possibilities"><div><span class="section-index">SIX ROUTES. NO ONE-SIZE-FITS-ALL ANSWER.</span><h2>There’s more than<br>one way <em>forward.</em></h2></div><div class="route-list">${[['01','Sell now','Turn today’s value into your next opportunity.'],['02','List and wait','Give the right buyer a little time.'],['03','Host longer','Keep useful compute doing useful work.'],['04','Yield while listed','Earn while the next owner finds you.'],['05','Repair','A small intervention. A longer story.'],['06','Harvest','Let the parts carry the value forward.']].map(r=>`<div><span>${r[0]}</span><h3>${r[1]}</h3><p>${r[2]}</p></div>`).join('')}</div></section><section class="exp-finale"><span class="section-index">FROM ONE ASSET TO THE WHOLE PICTURE</span><h2>Now imagine<br><em>your entire fleet.</em></h2><p>Every passport. Every possibility. One place to see the next move.</p><a class="experience-button" href="#overview">Explore the demo workspace <span>↗</span></a><div class="finale-features"><span>Asset passports</span><span>Fleet Command</span><span>What-if Lab</span><span>Opportunity Radar</span></div></section><footer class="exp-footer"><a href="#home" class="exp-logo">ReCompute®</a><span>Value, redirected.</span><small>Interactive concept · Illustrative data · No real transactions</small></footer>`}
function storyContent(){const a=assets[1],v=calculate(a,storyUtil);if(chapter===0)return `<div class="story-card meet-card"><div class="story-object">${gpuArt()}<span class="object-id">RC-002 / NORTHSTAR DEMO FLEET</span></div><div class="story-copy"><span class="chapter-label">01 / MEET IT</span><h3>Still powerful.<br>Just between jobs.</h3><p>This A100 spent 29 months doing what it does best. Now the workload has moved on. The hardware hasn’t lost its potential.</p><div class="human-stats"><div><strong>80 GB</strong><span>of memory</span></div><div><strong>94%</strong><span>demo health score</span></div></div><button class="experience-button" data-next>Look a little closer <span>→</span></button></div></div>`;if(chapter===1)return `<div class="story-card"><div class="editorial-passport"><div class="row"><span>RECOMPUTE / ASSET PASSPORT</span><span>↗</span></div><h4>NVIDIA A100</h4><p>Every asset deserves to be understood.</p><div class="passport-lines"><div><span>Condition</span><b>Healthy · 94 / 100</b></div><div><span>Memory diagnostics</span><b>Passed in demo</b></div><div><span>Current resale estimate</span><b>$11,200</b></div><div><span>Before a transfer</span><b>Data wipe required</b></div></div><div class="passport-stamp">RC—002 <span>ILLUSTRATIVE PASSPORT</span></div></div><div class="story-copy"><span class="chapter-label">02 / UNDERSTAND IT</span><h3>A passport.<br>Not just a price tag.</h3><p>Condition. History. Repairability. Security. A useful decision starts with the whole asset—not a number in a spreadsheet.</p><p class="story-aside">This one is healthy. No repair is needed. So the real question is: earn more from it, or move on?</p><button class="experience-button" data-next>Explore its futures <span>→</span></button></div></div>`;if(chapter===2)return `<div class="story-card futures-card"><div class="future-options"><span class="chapter-label">THREE POSSIBLE NEXT CHAPTERS</span>${[['sell','Sell it now',v.sale,'Cash today. A clean next step.'],['host','Keep it working',v.host,'90 days of income, then a sale.'],['hybrid','Earn while it’s listed',v.hybrid,'Income until a sale on day 45.']].map(r=>`<button class="future-option ${storyRoute===r[0]?'chosen':''}" data-route="${r[0]}" aria-pressed="${storyRoute===r[0]}"><span class="option-ring"></span><span><b>${r[1]}</b><small>${r[3]}</small></span><strong>${money(r[2])}</strong></button>`).join('')}<p class="model-note">Estimated total net value, including resale. Demo assumptions—not a quote.</p></div><div class="story-copy"><span class="chapter-label">03 / EXPLORE ITS FUTURES</span><h3>The answer changes.<br><em>Try changing the question.</em></h3><p>How busy could you keep this GPU? Move the slider and watch the economics respond.</p><label class="story-slider" for="storyUtil"><span>Expected utilization <b id="story-util-value">${storyUtil}%</b></span><input id="storyUtil" type="range" min="10" max="100" value="${storyUtil}"></label><p class="story-aside">90 days · $0.12/kWh · 3% monthly depreciation · hosting and selling fees included.</p><button class="experience-button" data-next>Choose this next chapter <span>→</span></button></div></div>`;let labels={sell:'A new owner. A new beginning.',host:'More work. More possibility.',hybrid:'Earning, until the next chapter.'};let val={sell:v.sale,host:v.host,hybrid:v.hybrid}[storyRoute];return `<div class="story-card decision-card"><div class="decision-poster"><span>THE NEXT CHAPTER / RC-002</span><div class="decision-symbol">↗</div><h4>${labels[storyRoute]}</h4><span>VALUE, REDIRECTED.</span></div><div class="story-copy"><span class="chapter-label">04 / MAKE A MOVE</span><h3>Your decision.<br>With the why behind it.</h3><p>You chose ${storyRoute==='sell'?'to sell now':storyRoute==='host'?'to keep hosting for 90 days':'to earn while listed'}. The model estimates <strong>${money(val)}</strong> in total net value.</p><p class="story-aside">${storyRoute==='sell'?'You prioritize immediate liquidity and avoid future market uncertainty.':`At ${storyUtil}% utilization, projected operating income is ${money(storyRoute==='hybrid'?v.net*.5:v.net)} over ${storyRoute==='hybrid'?45:90} days. Lower demand or resale prices could change the outcome.`} Next, save a plan and track what actually happens.</p><button class="experience-button" id="saveStory">Take this into the workspace <span>↗</span></button><button class="story-back" data-chapter="2">← Revisit the possibilities</button><small class="model-note">Saves a demo decision. No sale or hosting is initiated.</small></div></div>`}
function refreshStory(){document.querySelector('#story-content').innerHTML=storyContent();document.querySelectorAll('[data-chapter]').forEach(b=>{b.classList.toggle('current',+b.dataset.chapter===chapter);if(+b.dataset.chapter===chapter)b.setAttribute('aria-current','step');else b.removeAttribute('aria-current')})}
document.addEventListener('click',e=>{let t=e.target.closest('[data-start-story],[data-chapter],[data-next],[data-route],#saveStory');if(!t)return;if(t.hasAttribute('data-start-story')){e.preventDefault();document.querySelector(t.hasAttribute('data-idea')?'.manifesto':'#story').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});return}if(t.dataset.chapter!==undefined){chapter=+t.dataset.chapter;refreshStory()}if(t.hasAttribute('data-next')){chapter=Math.min(3,chapter+1);refreshStory()}if(t.dataset.route){storyRoute=t.dataset.route;refreshStory()}if(t.id==='saveStory'){let ok=addPlan(assets[1],{sell:0,host:2,hybrid:3}[storyRoute]);if(ok){let v=calculate(assets[1],storyUtil);saved.plans[saved.plans.length-1].expected={sell:v.sale,host:v.host,hybrid:v.hybrid}[storyRoute];persist()}location.hash='outcomes';toast(ok?'Your next chapter is saved. Track the outcome here.':'This asset already has a plan. You can review it here.')}});
document.addEventListener('input',e=>{if(e.target.id!=='storyUtil')return;storyUtil=+e.target.value;document.querySelector('#story-util-value').textContent=storyUtil+'%';let v=calculate(assets[1],storyUtil);document.querySelectorAll('[data-route]').forEach(b=>b.querySelector('strong').textContent=money({sell:v.sale,host:v.host,hybrid:v.hybrid}[b.dataset.route]))});
